validator:
function validate(input) {
  const [{ Followers = [] }] = input;
  const pairs = new Set();
  for (const [user, follower] of Followers) {
    if (user === null || follower === null) return 'Followers rows may not contain null.';
    const key = `${user},${follower}`;
    if (pairs.has(key)) return `(${user}, ${follower}) appears twice in Followers.`;
    pairs.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const users = small ? 5 : 200;
  const target = small ? pick(9) : 2000;
  const seen = new Set();
  const Followers = [];
  // Draw distinct pairs; give up on a draw after a few collisions so small pools still finish.
  for (let tries = 0; Followers.length < target && tries < target * 10; tries++) {
    const user = pick(users), follower = pick(users);
    if (user === follower) continue;
    const key = `${user},${follower}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Followers.push([user, follower]);
  }
  return [{ Followers }];
}
